```python
import argparse
import json
import re

from streamlink.plugin import Plugin, PluginArguments, PluginArgument
from streamlink.plugin.api import validate
from streamlink.stream import HLSStream, HTTPStream

API_CHANNEL_INFO = "http://ok.ru/dk?cmd=videoPlayerMetadata&mid={0}"
API_STREAMING = "https://ok.ru/rt/0.0.5240.rdtl"

_url_re = re.compile(r"""
    https?://(?:www\.)?ok\.ru/
    (?:
        live/(?P<live_id>\d+)
        |
        video/(?P<vod_id>\d+)
    )
""", re.VERBOSE)

_schema_vod = validate.Schema(
    {
        "movie": {
            "title": validate.text,
            "movieId": validate.text
        },
        "videos": [
            {
                "name": validate.text,
                "url": validate.url()
            }
        ]
    }
)

_schema_live = validate.Schema(
    {
        "streams": [
            {
                "url": validate.url(),
                "type": validate.text
            }
        ]
    }
)


class Okru(Plugin):
    arguments = PluginArguments(
        PluginArgument(
            "mobile",
            action="store_true",
            help="Use mobile streams"
        )
    )

    @classmethod
    def can_handle_url(cls, url):
        return _url_re.match(url) is not None

    def _get_streams_vod(self, vod_id):
        json_data = self.session.http.get(
            API_CHANNEL_INFO.format(vod_id)).json()

        metadata = self.session.http.json(
            self.session.http.get(API_CHANNEL_INFO.format(vod_id)),
            schema=_schema_vod)

        self.logger.debug("Title: {0}".format(metadata["movie"]["title"]))

        for video in metadata["videos"]:
            self.logger.debug("name: {0}".format(video["name"]))
            if "HLS" in video["name"]:
                yield HLSStream(self.session, video["url"])
            elif "DASH" in video["name"]:
                # DASH streams not supported
                continue
            else:
                yield HTTPStream(self.session, video["url"])

    def _get_streams_live(self, live_id):
        json_data = json.loads(self.session.http.get(
            API_STREAMING,
            params={"cmd": "getStreaming",
                    "mid": live_id}).text)

        for stream in json_data["streams"]:
            if "hls" in stream["type"]:
                yield HLSStream(self.session, stream["url"])
            elif "dash" in stream["type"]:
                # DASH streams not supported
                continue
            else:
                yield HTTPStream(self.session, stream["url"])

    def _get_streams(self):
        match = _url_re.match(self.url)
        live_id = match.group("live_id")
        vod_id = match.group("vod_id")

        if live_id:
            return self._get_streams_live(live_id)
        elif vod_id:
            return self._get_streams_vod(vod_id)


__plugin__ = Okru
```

